const D = { energy:.55, density:.5, speed:1, scale:1, wind:.6, alpha:.55, hue:34, x:.5, y:.55, style:'grit', act:'blow', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2=(h,s,v)=>{h=md(h,360)/60;s=clp(s,0,1);v=clp(v,0,1);const c=v*s,x=c*(1-Math.abs(h%2-1)),m=v-c;let r=0,g2=0,b=0;
  if(h<1){r=c;g2=x;}else if(h<2){r=x;g2=c;}else if(h<3){g2=c;b=x;}else if(h<4){g2=x;b=c;}else if(h<5){r=x;b=c;}else{r=c;b=x;}
  return [(r+m)*255,(g2+m)*255,(b+m)*255];};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'blow';
const isBowl=st==='dust_bowl', isSch=st==='schlieren', isMica=st==='mica';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

// ---- cached wind-stretched turbulence sheet (tiles in x) ----
const key=W+'x'+Hh+'|'+P.seed+'|'+st;
if(!S.sh||S.key!==key){
  const bw=200, bh=Math.max(80,Math.round(200*Hh/W*1.3));
  if(!S.sh||S.bw!==bw||S.bh!==bh){ S.sh=createGraphics(bw,bh); S.sh.pixelDensity(1); S.bw=bw; S.bh=bh; }
  const g=S.sh;
  const FX=[1,2,3,5,8], FY=[2.3,5.1,9.7,17.3,29.1];
  const PH=[fr(1)*6.283,fr(2)*6.283,fr(3)*6.283,fr(4)*6.283,fr(5)*6.283];
  g.loadPixels();
  for(let yy=0;yy<bh;yy++){
    for(let xx=0;xx<bw;xx++){
      const ux=xx/bw, vy=yy/bh;
      let v=0, amp=1, tot=0;
      for(let o=0;o<5;o++){
        const s1=Math.sin(6.283*FX[o]*ux+6.283*FY[o]*vy+PH[o]);
        v+=amp*(isBowl?s1:Math.abs(s1)*2-1); // ridged = filamentary sand; smooth = soft dust-bowl mass
        tot+=amp; amp*=0.56;
      }
      v=v/tot*0.5+0.5;
      let a,col;
      if(isSch){ const bnd=frc(v*7); a=Math.pow(Math.abs(bnd*2-1),2.2)*205; col=hsb2(md(H+180,360),0.10,lrp(0.34,0.96,v)); }
      else if(isMica){ a=Math.pow(clp(v,0,1),3.2)*160; col=hsb2(md(H+lrp(-8,14,v),360),lrp(0.30,0.06,v),lrp(0.42,1,v)); }
      else if(isBowl){ a=Math.pow(clp(v,0,1),1.15)*228; col=hsb2(md(H+lrp(-4,8,v),360),lrp(0.26,0.12,v),lrp(0.30,0.86,v)); }
      else { a=Math.pow(clp(v,0,1),1.7)*212; col=hsb2(md(H+lrp(-10,16,v),360),lrp(0.52,0.20,v),lrp(0.36,1,v)); }
      const p=4*(yy*bw+xx);
      g.pixels[p]=col[0]; g.pixels[p+1]=col[1]; g.pixels[p+2]=col[2]; g.pixels[p+3]=a;
    }
  }
  g.updatePixels();
  S.key=key;
}

// ---- storm state ----
let envA=1, envG=1;
if(act==='gusting'){ envA=0.68+0.9*K.intensity; envG=1.9; }
else if(act==='whiteout'){ envA=0.85+1.0*Math.pow(clp(0.5+0.5*Math.sin(K.t*0.037),0,1),1.5); envG=1.2; }
const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
// incommensurate real-time gust envelope — never re-phases on the 8s gate
const gust=0.54+0.28*Math.sin(K.t*0.157*P.speed)+0.16*Math.sin(K.t*0.383*P.speed+2.1)+0.10*Math.sin(K.t*0.071*P.speed+0.9);
const wd=P.wind, ws=(Math.abs(wd)*0.85+0.15)*P.speed;
const sgn=wd<0?-1:1;
const cx=P.x*W, cy=P.y*Hh;

// ---- parallax dust sheets (each blitted twice to wrap in x) ----
const NL=3;
for(let l=0;l<NL;l++){
  const dep=l/(NL-1||1);
  const sc=(sgn*lrp(0.030,0.115,dep)*ws + (l===1?-0.011:l===2?0.007:0.014)); // layers slide against each other even at wind 0
  const off=frc(K.t*sc + fr(l*3+40));
  const dh=Hh*1.3, oy=-Hh*0.15 + Math.sin(K.t*(0.043+l*0.029)+fr(l+9)*6.283)*Hh*0.06;
  const sw=W*lrp(1.35,0.85,dep)*clp(P.scale,0.3,2.4);
  const ox=-off*sw;
  const la=(isSch?0.34:isMica?0.30:0.46)*al*envA*gust*(0.42+0.95*en)*lrp(0.55,1.15,dep)*(1+A.rms*0.5);
  if(la<0.01) continue;
  tint(0,0,100,clp(la,0,1)*100);
  image(S.sh, ox, oy, sw, dh);
  image(S.sh, ox+sw, oy, sw, dh);
  if(ox+sw*2 < W) image(S.sh, ox+sw*2, oy, sw, dh);
  noTint();
}

// ---- travelling gust front (big soft density wave sweeping through) ----
{
  const gp=frc(K.t*0.083*ws*envG+fr(77))*1.5-0.25;
  const gx=(sgn>0?gp:1-gp)*W, gw=W*lrp(0.16,0.52,gust)*clp(P.scale,0.3,2.4);
  const gc=hsb2(isSch?md(H+180,360):md(H+6,360), isSch?0.08:isBowl?0.18:0.40, isSch?0.78:0.86);
  const ga=clp(0.30*al*envA*(0.3+en)*envG*(0.5+0.5*gust),0,0.62);
  const gr=drawingContext.createLinearGradient(gx-gw,0,gx+gw,0);
  gr.addColorStop(0,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+',0)');
  gr.addColorStop(0.5,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+','+ga.toFixed(3)+')');
  gr.addColorStop(1,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+',0)');
  drawingContext.fillStyle=gr;
  drawingContext.fillRect(Math.max(0,gx-gw),0,Math.min(W,gw*2),Hh);
}

// ---- saltating grains streaking downwind ----
if(!isSch){
  const ng=Math.round(lrp(40,230,dn));
  for(let i=0;i<ng;i++){
    const dep=fr(i*3+2);
    const spd=lrp(0.10,0.46,dep)*ws*3.2;
    const lane=fr(i*3+1);
    let gy=lane*Hh*1.1-Hh*0.05;
    gy+=Math.sin(K.t*(0.9+dep*2.4)+fr(i*3+5)*6.283)*u*0.012*(0.4+en); // saltation hop
    const fall=clp(1-Math.abs(gy-cy)/(Hh*lrp(0.95,0.42,dn)),0.08,1);
    const gx=(frc(fr(i*3+3)+K.t*spd*sgn)*1.2-0.1)*W;
    const lat=clp(1-Math.abs(gx-cx)/(W*1.1),0.15,1);
    const ln=u*lrp(0.006,0.055,dep)*(0.35+en*1.5)*clp(P.scale,0.3,2.4)*(0.4+Math.abs(wd));
    const aa=al*envA*gust*fall*lat*lrp(0.30,0.95,dep)*(isMica?1.15:0.85);
    if(aa<0.03) continue;
    if(isMica){
      const tw=Math.pow(0.5+0.5*Math.sin(K.t*(2.1+dep*4.7)+fr(i*7+3)*6.283),3);
      noStroke(); fill(md(H+lrp(-6,20,tw),360),lrp(24,4,tw),lrp(58,100,tw),(24+70*tw)*aa);
      circle(gx,gy,u*0.0035*clp(P.scale,0.3,2.4)*(0.6+dep*1.4)*(1+tw*1.3));
      stroke(md(H+10,360),8,100,52*tw*aa); strokeWeight(Math.max(0.4,u*0.0009));
      line(gx-ln*0.4*tw,gy,gx+ln*0.4*tw,gy); noStroke();
    } else {
      stroke(md(H+lrp(-8,14,dep),360), isBowl?lrp(22,8,dep):lrp(48,18,dep), lrp(52,100,dep), (26+58*dep)*aa);
      strokeWeight(Math.max(0.4,lrp(0.5,2.0,dep)*clp(P.scale,0.3,2.4)));
      line(gx,gy,gx-sgn*ln,gy+ln*0.13);
    }
  }
}

blendMode(BLEND); drawingContext.shadowBlur=0; noTint();
